export function getRecipeById(id: string | undefined): Recipe | undefined {
  return RECIPES.find((r) => r.id === id);
}

export function getRelatedRecipes(currentId: string, category: RecipeCategory, limit = 3): Recipe[] {
  return RECIPES.filter((r) => r.id !== currentId && r.category === category).slice(0, limit);
}

export function formatPublishedDate(dateStr: string): string {
  return new Date(dateStr).toLocaleDateString("en-US", { year: "numeric", month: "long", day: "numeric" });
}

export function toIsoDuration(minutes: number): string {
  if (minutes < 60) return `PT${minutes}M`;
  const h = Math.floor(minutes / 60);
  const m = minutes % 60;
  return m > 0 ? `PT${h}H${m}M` : `PT${h}H`;
}

export function getCategorySlug(cat: RecipeCategory): string {
  return CATEGORY_TO_SLUG[cat];
}
